head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSecugrpID = "";
scwin.notiId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        setInsertReadyStatus = "I";
        tar.style.display = "none";
        getId = $c.frame.path("../").fn_getPrtdepoId;
        scwin.notiId = getId();

        // alert("notiId="+notiId);

        if (scwin.notiId !== "input") {
            buttonSet.setUpdateStatus();
            await scwin.read();
            /* 20081007 조치여부가 1이면 체크..만료일은 조회할때 1년을 더해서 가져온다. */
            if (dts_readPrtdepo.getCellData(1, "ACT_YN") === "1") {
                chk_ActYn.setValue(1);
            }
        } else {
            buttonSet.setInsertStatus();
            const sbmOptions = {
                id : "sbm_dts_savePrtdepo",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_savePrtdepo=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_savePrtdepo.insertRow();
        }

        /*
        combo의 내용들이 다른 combo에 따라 동적으로 변동되기 때문에 bind를 이용한 data처리는 불가능
        조회 및 저장시 dataset에 coombo들과 관련된 값들을 직접저장해야 한다.
         */
        $c.pdc.fn_filCodCtr(cmb_PrtdepoPrnTpCd, codArrAtrTyp, undefined); // 보호예수대상자구분코드
        $c.pdc.fn_filCodCtr(cmb_PrtdepoObjKindCd, codArrObjKnd, undefined); // 보호예수대상종류코드

        if (js_market === '1') {
            $c.pdc.fn_filCodCtr(cmb_PrtdepoRsnCd, codArrRsnCod_U, undefined); // 보호예수사유코드

        } else if (js_market === '2') {
            $c.pdc.fn_filCodCtr(cmb_PrtdepoRsnCd, codArrRsnCod_K, undefined); // 보호예수사유코드

        } else if (js_market === '6') {
            $c.pdc.fn_filCodCtr(cmb_PrtdepoRsnCd, codArrRsnCod_N, undefined); // 보호예수사유코드

        }

        // 2008-12-01 기타보호예수사유코드
        $c.pdc.fn_filCodCtr(cmb_MiscPrtdepoRsnCd, codArrMiscRsnCd, undefined);
        cmb_PrtdepoObjKindCd.BindColVal = dts_readPrtdepo.getCellData(1, "PRTDEPO_OBJ_KIND_CD");
        cmb_PrtdepoPrnTpCd.BindColVal = dts_readPrtdepo.getCellData(1, "PRTDEPO_PRN_TP_CD");
        cmb_PrtdepoRsnCd.BindColVal = dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_CD");
        cmb_PrtdepoRsnMngrghtTpCd.BindColVal = dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_MNGRGHT_TP_CD");
        cmb_PrtdepoRsnFncTpCd.BindColVal = dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_FNC_TP_CD");

        // 2008-12-01 보호예수사유비고, 기타보호예수사유코드, 기타보호예수사유비고
        txb_PrtdepoRsnRemk.setValue(dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_REMK"));
        cmb_MiscPrtdepoRsnCd.BindColVal = dts_readPrtdepo.getCellData(1, "MISC_PRTDEPO_RSN_CD");
        txb_MiscPrtdepoRsnRemk.setValue(dts_readPrtdepo.getCellData(1, "MISC_PRTDEPO_RSN_REMK"));

        // 2008-12-04 기타보호예수개시일자, 기타보호예수종료일자
        med_MiscPrtdepoStrtDd.setValue(dts_readPrtdepo.getCellData(1, "MISC_PRTDEPO_STRT_DD"));
        med_MiscPrtdepoEndDd.setValue(dts_readPrtdepo.getCellData(1, "MISC_PRTDEPO_END_DD"));

        // 2008-12-15 조치횟수
        txb_Cnt.setValue(dts_readPrtdepo.getCellData(1, "ACT_YN"));
        // alert("조치횟수 -->"+dts_readPrtdepo.NameString(1, "ACT_YN"));
        chk_ActYn.hide(); // 조치여부 안보이도록 처리
        btn_Cal.hide();
        txb_Cnt.hide();
        med_RsnOccrDdtm.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40209.onpageload" });
    }
};

