/**
 * @method
 * @name dts_readPrtdepo_OnLoadCompleted
 * @description dts_readPrtdepo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_readPrtdepo_OnLoadCompleted = function(rowcount) {
    try {
        // dataset의 처리부분.  combo을 설정하는 부분은 bind을 이용할 수 없다. 나머지는 bind로 처리

        cmb_PrtdepoObjKindCd.setSelectedIndex(cmb_PrtdepoObjKindCd.indexOfColumn("code", dts_readPrtdepo.getCellData(1, "PRTDEPO_OBJ_KIND_CD"))); // 보호예수대상종류코드
        $c.pdc.fn_setCodCtr(cmb_PrtdepoObjKindCd);
        cmb_PrtdepoPrnTpCd.setSelectedIndex(cmb_PrtdepoPrnTpCd.indexOfColumn("code", dts_readPrtdepo.getCellData(1, "PRTDEPO_PRN_TP_CD"))); // 보호예수대상구분코드
        $c.pdc.fn_setCodCtr(cmb_PrtdepoObjTpCd);
        cmb_PrtdepoRsnCd.setSelectedIndex(cmb_PrtdepoRsnCd.indexOfColumn("code", dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_CD"))); // 보호예수사유코드
        $c.pdc.fn_setCodCtr(cmb_PrtdepoRsnCd);
        cmb_PrtdepoRsnMngrghtTpCd.setSelectedIndex(cmb_PrtdepoRsnMngrghtTpCd.indexOfColumn("code", dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_MNGRGHT_TP_CD"))); // 보호예수사유경영권구분코드
        $c.pdc.fn_setCodCtr(cmb_PrtdepoRsnMngrghtTpCd);
        cmb_PrtdepoRsnFncTpCd.setSelectedIndex(cmb_PrtdepoRsnFncTpCd.indexOfColumn("code", dts_readPrtdepo.getCellData(1, "PRTDEPO_RSN_FNC_TP_CD"))); // 보호예수사유재무구분코드

        // 2008-12-01 기타보호예수사유코드
        cmb_MiscPrtdepoRsnCd.setSelectedIndex(cmb_MiscPrtdepoRsnCd.indexOfColumn("code", dts_readPrtdepo.getCellData(1, "MISC_PRTDEPO_RSN_CD")));
        $c.pdc.fn_setCodCtr(cmb_MiscPrtdepoRsnCd);

        // binder의 처리 후 하단 일부매각가능시작일~ 에 대한 값을 산출
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40209.dts_readPrtdepo_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&SCREN_ID=" + "ULDSTF40209.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&notiId=" + scwin.notiId;
    const sbmOptions = {
        id : "sbm_dts_readPrtdepo",
        action : "/ProtectedDepositionManagement.do",
        ref : "",
        target : "dts_readPrtdepo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("ACT_YN ----> "+dts_readPrtdepo.NameString(1, "ACT_YN"));

};

/**
 * @method
 * @name update
 * @description validation check//
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // validation check//

    if (txb_isur_cd.getValue() === "" && txb_com_nm.getValue() === "") {
        await $c.win.alert("[등록할 법인]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    /*
    		if(med_RsnOccrDdtm.Text == ""){
    			alert( getMessageParam("MSG-A005", "사유발생일") );
    			med_RsnOccrDdtm.Focus();
    			return ;
    		}
     */
    med_RsnOccrDdtm.setValue("");
    if (txb_nm.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "성명"));
        txb_nm.focus();
        return;
    }

    /*생년월일은 필수사항 아님
    		if(txb_RESDBZ_REG_NO.value == ""){
    			alert( getMessageParam("MSG-A005", "생년월일(사업자번호)") );
    			txb_RESDBZ_REG_NO.focus();
    			return ;
    		}
     */
    if (med_PrtdepoShrs.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유대상주식"));
        med_PrtdepoShrs.focus();
        return;
    }
    if (cmb_PrtdepoPrnTpCd.BindColVal === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "대상자구분"));
        cmb_PrtdepoPrnTpCd.focus();
        return;
    }
    if (cmb_PrtdepoObjKindCd.BindColVal === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유대상종류"));
        cmb_PrtdepoObjKindCd.focus();
        return;
    }
    if (cmb_PrtdepoRsnCd.BindColVal === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유사유"));
        cmb_PrtdepoRsnCd.focus();
        return;
    }

    // 2009.04.20 보호예수 사유가 해당사항없음이면 기간입력을 하지 않는다.
    if (cmb_PrtdepoRsnCd.BindColVal === "70") {
        if (med_PrtdepoStrtDd.getValue() !== "" || med_PrtdepoEndDd.getValue() !== "") {
            await $c.win.alert("의무보유사유가 [해당사항없음] 일때는 의무보유기간을 입력하지 않습니다.");
            med_PrtdepoStrtDd.focus();
            return;
        }
    } else {
        if (med_PrtdepoStrtDd.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유시작일"));
            med_PrtdepoStrtDd.focus();
            return;
        }
        if (med_PrtdepoEndDd.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유종료일"));
            med_PrtdepoEndDd.focus();
            return;
        }
    }

    /*
    		if(cmb_MiscPrtdepoRsnCd.BindColVal == ''){
    			alert("기타보호예수사유코드를 입력하세요");
    			cmb_MiscPrtdepoRsnCd.Focus();
    			return;
    		}

            //2009.04.20 기타보호예수 사유가 해당사항없음이면 기간입력을 하지 않는다.
    		if(cmb_MiscPrtdepoRsnCd.BindColVal == '04'){
    			if(med_MiscPrtdepoStrtDd.Text != "" || med_MiscPrtdepoEndDd.Text != ""){
    				alert("기타보호예수사유가 [해당사항없음] 일때는 기타보호예수기간을 입력하지 않습니다.");
    				med_MiscPrtdepoStrtDd.Focus();
    				return;
    			}
    		}else{
    			if(med_MiscPrtdepoStrtDd.Text == ""){
    				alert( getMessageParam("MSG-A005", "기타보호예수시작일") );
    				med_MiscPrtdepoStrtDd.Focus();
    				return ;
    			}
    			if(med_MiscPrtdepoEndDd.Text == ""){
    				alert( getMessageParam("MSG-A005", "기타보호예수종료일") );
    				med_MiscPrtdepoEndDd.Focus();
    				return ;
    			}
    		}
     */

    if (await scwin.dateCheck() === false) {
        return;
    }
    if (await scwin.dateCheckMisc() === false) {
        return;
    }

    /* 20081015 조치여부 DB저장 */
    let act_yn_flag = "";
    if (chk_ActYn.checked) {
        // 조치여부에 체크표시를 하면 '1' 예로 들어감..
        act_yn_flag = "1";
    } else {
        act_yn_flag = "2";
    }
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_PRN_TP_CD", cmb_PrtdepoPrnTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_OBJ_KIND_CD", cmb_PrtdepoObjKindCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_OBJ_TP_CD", cmb_PrtdepoObjTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_CD", cmb_PrtdepoRsnCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_MNGRGHT_TP_CD", cmb_PrtdepoRsnMngrghtTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_FNC_TP_CD", cmb_PrtdepoRsnFncTpCd.BindColVal);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "ACT_YN", act_yn_flag);
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "PRTDEPO_RSN_REMK", txb_PrtdepoRsnRemk.getValue()); // 2008-12-01 보호예수사유비고
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_CD", cmb_MiscPrtdepoRsnCd.BindColVal); // 2008-12-01 기타보호예수사유코드
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_REMK", txb_MiscPrtdepoRsnRemk.getValue()); // 2008-12-01 기타보호예수사유비고

    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_STRT_DD", med_MiscPrtdepoStrtDd.getValue()); // 2008-12-01 기타보호예수개시일자
    dts_readPrtdepo.setCellData(dts_readPrtdepo.getRowPosition(), "MISC_PRTDEPO_END_DD", med_MiscPrtdepoEndDd.getValue()); // 2008-12-01 기타보호예수종료일자

    // alert(dts_readPrtdepo.Text); //데이타셋내용확인

    let rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/ProtectedDepositionManagement.do",
            ref : "dts_readPrtdepo",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name save
 * @description validation check//
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // validation check//
    if (txb_isur_cd.getValue() === "" && txb_com_nm.getValue() === "") {
        await $c.win.alert("[등록할 법인]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    /*
