    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_RSN_REMK", txb_MiscPrtdepoRsnRemk.getValue()); // 2008-12-01 기타보호예수사유비고

    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_STRT_DD", med_MiscPrtdepoStrtDd.getValue()); // 2008-12-01 기타보호예수개시일자
    dts_savePrtdepo.setCellData(dts_savePrtdepo.getRowPosition(), "MISC_PRTDEPO_END_DD", med_MiscPrtdepoEndDd.getValue()); // 2008-12-01 기타보호예수종료일자

