 */
scwin.delete = async function() {
    let rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_deletePrtdepo.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_deletePrtdepo.insertRow();
        dts_deletePrtdepo.setCellData(1, "PRTDEPO_ID", scwin.notiId);
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/ProtectedDepositionManagement.do",
            ref : "dts_deletePrtdepo",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

