/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_isur_cd.setValue(arrPar[0].ISUR_CD);
    txb_com_nm.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(med_PrtdepoStrtDd.getValue(), '10') > parseInt(med_PrtdepoEndDd.getValue(), '10')) {
        await $c.win.alert("[의무보유기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        med_PrtdepoStrtDd.setValue("");
        med_PrtdepoEndDd.setValue("");
        return false;
    }
};

/**
 * @method
 * @name dateCheckMisc
 * @description date Check Misc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheckMisc = async function() {
    if (parseInt(med_MiscPrtdepoStrtDd.getValue(), '10') > parseInt(med_MiscPrtdepoEndDd.getValue(), '10')) {
        await $c.win.alert("[기타의무보유기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        med_MiscPrtdepoStrtDd.setValue("");
        med_MiscPrtdepoEndDd.setValue("");
        return false;
    }
};
